        >
          <div
            onClick={(e) => e.stopPropagation()}
            style={{
              maxWidth: 'min(1200px, 96vw)',
              maxHeight: '92vh',
              borderRadius: '12px',
              overflow: 'hidden',
              border: '1px solid rgba(255,255,255,0.25)',
              background: 'transparent'
            }}
          >
            {hallSlides.length ? (
              <img
                src={hallSlides[hallSlideIndex]}
                alt="Hall/Room View Full"
                style={{
                  width: '100%',
                  height: '100%',
                  maxHeight: '92vh',
                  objectFit: 'contain',
                  display: 'block'
                }}
